function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#saveState').textContent='已保存在当前浏览器。'}catch{$('#saveState').textContent='浏览器存储不可用，请导出保存。'}document.dispatchEvent(new Event('travel:change'));}
function fav(id){state.fav=state.fav.includes(id)?state.fav.filter(x=>x!==id):[...state.fav,id];save();renderHotels();renderSpots();renderXhsNotes()}
function favbtn(id){return `<button data-fav="${id}" aria-pressed="${state.fav.includes(id)}">${state.fav.includes(id)?'♥ 已收藏':'♡ 收藏'}</button>`}
function renderHotels(){const q=$('#hotelq').value.toLowerCase();const list=hotels.filter(h=>h.id!=='h8'&&(h.name+h.area+(h.room||'')).toLowerCase().includes(q)&&h.score>=Number($('#minscore').value)&&(!$('#hotelFav').checked||state.fav.includes(h.id))&&($('#hotelTier').value==='all'||(h.tier||'comfort')===$('#hotelTier').value)&&(!$('#fiveVerified').checked||h.capacity>=5));$('#hotelCount').textContent=list.length+'家历史候选 · 本轮未刷新其三晚价格';$('#hotels').innerHTML=list.map(h=>`<article class="card"><span class="score">${h.score}</span><span class="micro">携程 / 5分制</span><h3>${esc(h.name)}</h3><p class="sub">${esc(h.area)}</p><p>${esc(h.desc)}</p><span class="pill">${h.tier==='whole'?'整套房型候选':h.tier==='economy'?'旧版经济酒店':'原度假候选'}</span><span class="pill ${h.capacity?'':'warn'}">${h.capacity?'平台房型明确6人':'五人容量待核'}</span>${h.tier==='whole'?`<h3>${esc(h.room)}</h3><p>${esc(h.evidence)}</p><p><b>预算目标：整套三晚≤¥2,500</b><br>约¥833／套晚 · 人均¥500／三晚<br><b>实际报价：未获取；未确认有房</b></p><details><summary>环境与整套核对事项</summary><p>${esc(h.limits)}</p></details>`:`<p><b>价格：未获取指定日期报价</b><br>原三间房方案保留作历史比较，未按当前两／三卧整套要求筛选。</p>`}<div class="actions">${favbtn(h.id)}${link(h.url||sources[0][1],h.url?'携程酒店页':'携程榜单')}${h.roomUrl?link(h.roomUrl,'核对具体房型'):''}${link(navlink(h.name),'地图搜索')}</div></article>`).join('')||'<p>没有匹配项。可取消“只看平台人数已明确”查看待核套房；这不代表它们已满足五人入住。</p>'}
function renderSpots(){const q=$('#placeq').value.toLowerCase();$('#spots').innerHTML=spots.filter(p=>(p.name+p.tag+p.desc).toLowerCase().includes(q)&&($('#kind').value==='全部'||p.kind===$('#kind').value)&&(!$('#placeFav').checked||state.fav.includes(p.id))).map(p=>`<article class="card"><span class="pill">${p.kind}</span><h3>${p.name}</h3><p class="sub">${p.tag}</p><p>${p.desc}</p><div class="actions">${favbtn(p.id)}${p.xhs?link(xhsById(p.xhs).url,'小红书原文'):link(sources[p.src][1],'资料来源')}${link(navlink(p.name),'高德搜索')}</div></article>`).join('')||'<p>没有匹配地点。</p>'}
function renderDay(){const w=weather[day];const rainy=$('#rain').checked;const base=state.tripStyle!=='comfort'&&economyPlans[day]?economyPlans[day]:plans[day];const chosen=state.tripStyle==='comfort'&&day===2&&state.route==='forest'&&!rainy?forestPlan:base;$('#routeChoice').hidden=day!==2||state.tripStyle!=='comfort';$('#route').value=state.route||'bamboo';$('#days').innerHTML=plans.map((p,i)=>`<button class="${i===day?'active':''}" data-day="${i}"><span>DAY 0${i+1} · ${['周二','周三','周四','周五'][i]}</span><b>10.${27+i}</b></button>`).join('');$('#daytitle').textContent=chosen.title;$('#weather').innerHTML=`<b>${w[0]} ${w[1]} · ${w[2]}</b> <span class="pill ${day>1?'warn':''}">${w[3]}</span><p>${w[4]}</p><small>${link(sources[w[5]][1],'中国天气网')} · 2026-10-22读取，非实况／非气候推测</small>`;$('#timeline').innerHTML=(rainy?base.rain:chosen.items).map(x=>`<article><small>${x[0]} · 暂定</small><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('');$('#dayNotes').innerHTML=state.tripStyle!=='comfort'?(day===1?link('https://www.zmnh.com/henryhtml/service_reference2.html','常设展免费与预约指南'):day===2?link('https://you.ctrip.com/sight/anji686/139895.html','余村开放信息'):''):day===1?('游记依据：'+link(xhsById('xhs-xiaohangkeng').url,'小杭坑半日体验')):day===2?('参考原文：'+link(xhsById(state.route==='forest'&&!rainy?'xhs-forest-now':'xhs-rain').url,state.route==='forest'&&!rainy?'金钱松当天笔记':'余村与餐饮线索')):'';}
function budget(){const labels=['当地租车与保障（3天额度，超时另计）',state.tripStyle==='homestay'?'整套民宿（五人×三晚总额）':'住宿（3间×3晚预留）','餐饮（5人×4天预留）','当地燃油','当地通行费','停车','门票与体验（五人总额）','机动预留','高铁往返（5人总额）','车站与门店接驳预留'];$('#budget').innerHTML=labels.map((x,i)=>`<label class="budgetline">${x}<input type="number" min="0" step="10" data-budget="${i}" value="${state.budget[i]}"></label>`).join('');totals()}
function totals(){const total=state.budget.reduce((a,b)=>a+Number(b),0);$('#total').textContent='¥'+total.toLocaleString();$('#per').textContent=Math.round(total/5).toLocaleString();$('#budgetGap').textContent=total>6000?'超出6000元目标 ¥'+(total-6000).toLocaleString():'距6000元上限还余 ¥'+(6000-total).toLocaleString();$('#budgetGap').classList.toggle('warn',total>6000)}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.tab){document.querySelectorAll('section').forEach(x=>x.classList.toggle('active',x.id===b.dataset.tab));document.querySelectorAll('.nav [data-tab]').forEach(x=>x.classList.toggle('active',x.dataset.tab===b.dataset.tab));window.scrollTo({top:0,behavior:'instant'});if(map)setTimeout(()=>map.invalidateSize(),80)}if(b.dataset.day!==undefined){day=Number(b.dataset.day);renderDay()}if(b.dataset.fav)fav(b.dataset.fav)});
['hotelq','minscore','hotelFav','hotelTier','fiveVerified'].forEach(id=>$('#'+id).addEventListener('input',renderHotels));['placeq','kind','placeFav'].forEach(id=>$('#'+id).addEventListener('input',renderSpots));$('#rain').addEventListener('change',renderDay);$('#route').addEventListener('change',e=>{state.route=e.target.value;save();renderDay()});$('#memo').value=state.memo;$('#memo').addEventListener('input',()=>{state.memo=$('#memo').value;save()});$('#budget').addEventListener('input',e=>{if(e.target.dataset.budget!==undefined){state.budget[Number(e.target.dataset.budget)]=Math.max(0,Number(e.target.value)||0);totals();save()}});
$('#export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify({version:7,trip:'2026-10-27/2026-10-30',...state},null,2)],{type:'application/json'}));a.download='安吉五人旅行记录.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};
$('#import').onchange=async e=>{try{const data=JSON.parse(await e.target.files[0].text());if(!Array.isArray(data.fav)||!data.fav.every(x=>typeof x==='string')||typeof data.memo!=='string'||!Array.isArray(data.budget)||![8,10].includes(data.budget.length)||!data.budget.every(x=>Number.isFinite(x)&&x>=0))throw Error();const extra=window.normalizeWorkspaceState?window.normalizeWorkspaceState(data):{};state=migrateTravelState({...extra,fav:data.fav,memo:data.memo,budget:data.budget,route:data.route==='forest'?'forest':'bamboo',wholeRevision:data.wholeRevision===1?1:undefined,economyRevision:data.economyRevision===1?1:undefined,tripStyle:data.tripStyle,previousBudget:Array.isArray(data.previousBudget)&&data.previousBudget.length===10&&data.previousBudget.every(v=>Number.isFinite(v)&&v>=0)?data.previousBudget:undefined});renderStyle();$('#memo').value=state.memo;save();renderHotels();renderSpots();renderXhsNotes();renderDay();budget();window.refreshWorkspace?.()}catch{$('#saveState').textContent='导入失败：请选择本工作台导出的有效JSON记录。'}};
renderStyle();$('#sourceList').innerHTML=sources.map(s=>`<li>${link(s[1],s[0])}<br><span class="sub">${s[2]}</span></li>`).join('');$('#maplinks').innerHTML=[{name:'安吉站'},...spots,...hotels,...(window.STAY_RESEARCH||[]).filter(p=>p.original&&p.id!=='h8')].map(p=>link(navlink(p.name),p.name)).join('');renderDay();renderHotels();renderSpots();renderXhsNotes();budget();
if(window.L){$('#map').replaceChildren();map=L.map('map').setView([30.60,119.58],10);let loaded=false;const tiles=L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'© OpenStreetMap contributors',maxZoom:17}).addTo(map);tiles.on('tileload',()=>loaded=true);setTimeout(()=>{if(!loaded){const n=document.createElement('p');n.className='note';n.textContent='底图未加载，可使用下方高德搜索；示意点位仍可点击。';$('#map').after(n)}},5000);[...spots,...hotels].filter(p=>p.pos).forEach(p=>{const m=L.circleMarker(p.pos,{radius:p.id[0]==='h'?9:7,color:'#fff',weight:2,fillColor:p.id[0]==='h'?'#b96937':'#365e45',fillOpacity:.95}).addTo(map).bindPopup(`<b>${p.name}</b><br>区域示意点位，入口待核<br>${link(navlink(p.name),'高德定位')}`);markers.push(m)});}

if(!window.L)$('#map').innerHTML='<div class="mapfallback">底图组件未能加载，请使用下方高德搜索查看地点。</div>';

function renderXhsNotes(){const q=$('#xhsq').value.toLowerCase();const type=$('#xhskind').value;$('#xhsCards').innerHTML=XHS_NOTES.filter(n=>(n.title+n.author+n.summary+n.detail+n.use+n.limit).toLowerCase().includes(q)&&(type==='全部'||type===n.category)&&(!$('#xhsFav').checked||state.fav.includes(n.id))).map(n=>`<article class="card"><span class="pill">${esc(n.category)}</span><span class="pill">原文已读取</span><h3>${esc(n.title)}</h3><p class="sub">${esc(n.author)} · ${esc(n.date)}</p><p>${esc(n.summary)}</p><p><b>放进本次行程：</b>${esc(n.use)}</p><details><summary>查看细节与核实边界</summary><p>${esc(n.detail)}</p><p class="note">${esc(n.limit)}</p></details><div class="actions">${favbtn(n.id)}${link(n.url,'打开原文')}${link('https://www.xiaohongshu.com/search_result?keyword='+encodeURIComponent(n.title),'按标题搜索')}</div><p class="note">读取：2026-10-22 · 只读原文，未联系作者</p></article>`).join('')||'<p>没有匹配的攻略，试试其他筛选。</p>'}
['xhsq','xhskind','xhsFav'].forEach(id=>$('#'+id).addEventListener('input',renderXhsNotes));


function renderStyle(){document.querySelectorAll('[data-style]').forEach(b=>{b.classList.toggle('active',b.dataset.style===state.tripStyle);b.setAttribute('aria-pressed',String(b.dataset.style===state.tripStyle))});const whole=state.tripStyle==='homestay';const economy=state.tripStyle==='economy';$('#hotelTier').value=whole?'whole':economy?'economy':'all';$('#fiveVerified').checked=whole;$('#styleLabel').textContent=whole?'整套民宿版 · 住宿三晚 ¥2,500 / 全程参考 ¥6,880':economy?'经济酒店旧版 · ¥6,000 / 人均 ¥1,200':'舒适参考 · 预算可自行调整';$('#styleDetail').textContent=whole?'两卧或三卧，五人同住一套；优先核人数与独享空间，住宿人均500元覆盖三晚。':'保留旧版供比较；当前住宿偏好是五人两卧或三卧整套。';$('#budgetAssumption').textContent=whole?'住宿整套三晚2500元，其余沿用省钱版额度，合计6880元／人均1376元。比原6000目标多880元，待实际车票、租车和房价核实后再压缩，不假定已省下。':economy?'旧版：3间×180元×3晚＝1620元；餐饮1000元。未按当前整套要求筛选。':'舒适参考：住宿5400元、餐饮2400元，均为规划额度。';$('#restoreBudget').disabled=!Array.isArray(state.previousBudget)}
function chooseStyle(style){const selected=style==='homestay'?homestayBudget:style==='economy'?economyBudget:budgetDefaults;if(state.tripStyle===style&&state.budget.every((v,i)=>v===selected[i]))return;state.previousBudget=state.budget.slice();state.tripStyle=style;state.budget=selected.slice();save();renderStyle();renderDay();renderHotels();budget();window.refreshWorkspace?.()}
document.querySelectorAll('[data-style]').forEach(b=>b.addEventListener('click',()=>chooseStyle(b.dataset.style)));
$('#restoreBudget').onclick=()=>{if(!Array.isArray(state.previousBudget))return;const prior=state.budget.slice();state.budget=state.previousBudget.slice();state.previousBudget=prior;save();budget()};
